const sources = new Map<string, string>();
function register(value: unknown, path: string) {
  if (typeof value === "string") { sources.set(value, path); return; }
  if (value && typeof value === "object") for (const [key, child] of Object.entries(value)) register(child, `${path}.${key}`);
}
register(UI_LABELS_FR.header, "header");

export function localizeHeaderUiLabel(source: string, locale: string): string | null {
  const voice = localizeVoiceUiLabel(source, locale);
  if (voice) return voice;
  const language = baseUiLocale(locale);
  if (language === "fr") return source;
  const index = languages.indexOf(language as typeof languages[number]);
  if (index < 0) return null;
  const explicit = rows[source]?.[index];
  if (validUiTranslation(source, explicit)) return explicit;
  const key = sources.get(source);
  if (!key) return null;
  const entry = key ? compiled.byKey[key as keyof typeof compiled.byKey] : undefined;
  const translated = (entry?.source === source ? (entry.translations as Record<string, string>)[language] : undefined)
    ?? (compiled.bySource as Record<string, Record<string, string>>)[source]?.[language];
  if (validUiTranslation(source, translated)) return translated;
  // Symbols and diagnostic identifiers have no linguistic content.
  if (["/", "<", ">", "<<", ">>", "IP", "AI real", "AI mock"].includes(source)) return source;
  return null;
}
